  const ratio = paired.map(o => (o.p.f / F.md.f[o.m.j]) ** 2), rm = ratio.length ? ratio.reduce((a, b) => a + b, 0) / ratio.length : null, spread = ratio.length > 1 ? Math.max(...ratio) - Math.min(...ratio) : 0;
