    <label class="f">Carga muerta adicional DW (kN/m)<input type="number" id="hlDW" step="0.5" min="0" value="${H.dw}"></label>
    <label class="f">Límite de flecha por carga viva<select id="hlLim"><option value="800" ${H.lim == 800 ? 'selected' : ''}>L/800 · vehicular</option><option value="1000" ${H.lim == 1000 ? 'selected' : ''}>L/1000 · con peatones</option></select></label></div>
