PG_DB.get('insp').then(v => { if (v && typeof v === 'object') { Object.keys(v).forEach(k => { if (!PG.I[k] || !PG.I[k].recs.length) PG.I[k] = v[k]; }); if (typeof S !== 'undefined' && ['inspmtc', 'deterioro'].includes(S.view)) render(); } });
function pgPhoto(file) { return new Promise((res, rej) => { const img = new Image(), u = URL.createObjectURL(file); img.onload = () => { const k = Math.min(1, 1280 / Math.max(img.width, img.height)), c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k); c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(u); res(c.toDataURL('image/jpeg', .78)); }; img.onerror = () => rej(new Error('No se pudo leer la imagen.')); img.src = u; }); }
