  const z = String(zone), fam = /arco/i.test(z) ? 'arco' : /montante/i.test(z) ? 'montante' : /pilar/i.test(z) ? 'pilar' : /tablero|vano/i.test(z) ? (I.type === 'viga' ? 'viga' : 'tablero') : /cord/i.test(z) ? 'cordón' : /diag/i.test(z) ? 'diagonal' : null, e = I.els.find(x => x.fam === fam);
